#include <stdio.h>

/* teste do desafio preco-com-decimais — counter_protocol (03-tdd 3.9.3).
   Fase SAIDA: a comparacao e por TEXTO (o %f do aluno, seis casas), nunca por
   igualdade de double. A captura acontece dentro do teste: freopen manda o
   stdout para um arquivo temporario proprio do cenario, fflush descarrega e o
   arquivo e lido de volta. O main e o relatorio sao do harness. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void precoComDecimais(void);

SM_TEST(os_dois_precos_com_seis_casas) {
    freopen("sm_saida_1.tmp", "w", stdout);
    precoComDecimais();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o preco do cafe", linha, "o cafe custa 3.500000\n",
              "o %f imprime 3.5 com seis casas: 3.500000");
    fgets(linha, 80, f);
    checa_str("o preco do bolo", linha, "o bolo custa 12.750000\n",
              "o %f imprime 12.75 com seis casas: 12.750000");
    fclose(f);
}

SM_TEST(a_saida_acaba_no_segundo_preco) {
    freopen("sm_saida_2.tmp", "w", stdout);
    precoComDecimais();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    fgets(linha, 80, f);
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba no segundo preco: nenhuma linha extra e aceita");
    fclose(f);
}

